fn to_uppercase(str1: &Vec<char>) -> Vec<char> {
    // Pre-allocate the result vector with the same length as the input
    let mut result = Vec::with_capacity(str1.len());

    // Iterate over each character in the input vector
    for &ch in str1.iter() {
        // Convert lowercase ASCII letters to uppercase; leave everything else unchanged
        result.push(ch.to_ascii_uppercase());
    }

    result
}

